import sys

def solve(n, k):
    if k == 1:
        return list(range(1, n + 1))

    result = [1]
    for i in range(2, n - k + 2):
        result.append(i)

    for i in range(n - k + 1, n + 1):
        result.append(result[-1] + 2)

    return result

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    k = int(data[1])
    result = solve(n, k)
    print(" ".join(map(str, result)))

if __name__ == "__main__":
